impl Solution{pub fn calculate(s:String)->i32{let mut st=vec![];let(mut r,mut n,mut sg)=(0,0,1);for c in s.chars().chain(std::iter::once('\0')){if c.is_ascii_digit(){n=n*10+c.to_digit(10).unwrap()as i32}else if c=='+'||c=='-'{r+=sg*n;n=0;sg=if c=='+'{1}else{-1}}else if c=='(' {st.push(r);st.push(sg);r=0;sg=1}else if c==')'{r+=sg*n;n=0;let x=st.pop().unwrap();let y=st.pop().unwrap();r=x*r+y}else if c=='\0'{r+=sg*n}}r}}
